def copy_images_to_gallery(apps, schema_editor):
    """Each product's single picture becomes the main picture of its gallery (same stored file)."""
    Product = apps.get_model("shop", "Product")
    ProductImage = apps.get_model("shop", "ProductImage")
    for product in Product.objects.exclude(image=""):
        ProductImage.objects.create(product=product, image=product.image.name, is_main=True, ordering=0)


def copy_back(apps, schema_editor):
    """Reverse: the main picture goes back to the single field."""
    ProductImage = apps.get_model("shop", "ProductImage")
    for image in ProductImage.objects.filter(is_main=True).select_related("product"):
        image.product.image = image.image.name
        image.product.save(update_fields=["image"])


